"""Write the VINS-Fusion YAML config from the cine_sensing_config JSON files.

The tuning comes from `vins.json` (or the active profile's copy). The camera YAML that
the config's `cam0_calib` names is written beside the config from the profile's
`vins_camera.json` when the profile has one; otherwise it is the `cam0_wide.yaml` that
the `vins` package installs. VINS resolves `cam0_calib` relative to the config's own
directory, so it is written as a relative path.

Usage: generate_vins_config.py [output_path]
"""

import os
import sys

try:
    import cine_sensing_config
    from cine_sensing_config import CameraConfig, VinsConfig
    from cine_sensing_config.constants import package_share_directory
except ImportError:
    print('Error: cine_sensing_config is not importable. Source the workspace install/setup.bash.')
    sys.exit(1)

PROFILE_CAMERA_CONFIG_NAME = 'vins_camera'
INSTALLED_CAMERA_DIRECTORY = os.path.join('config', 'rpi_camera_v3')


def profile_camera_values():
    """Return the active profile's camera values, or None when it defines none."""
    camera_path = cine_sensing_config.config_file_path(PROFILE_CAMERA_CONFIG_NAME)
    if not camera_path.is_file():
        return None

    return cine_sensing_config.load(PROFILE_CAMERA_CONFIG_NAME)


def installed_camera_file(cam0_calib, share_directory_lookup):
    """Return the absolute path of `cam0_calib` inside the installed `vins` package.

    Raises FileNotFoundError naming the path when the file is not installed.
    """
    if os.path.isabs(cam0_calib):
        return cam0_calib

    camera_path = os.path.join(share_directory_lookup('vins'), INSTALLED_CAMERA_DIRECTORY, cam0_calib)
    if not os.path.isfile(camera_path):
        raise FileNotFoundError(f'VINS camera file not found: {camera_path}')

    return camera_path


def _write_yaml_entries(file_handle, values, indent=''):
    for key, value in values.items():
        if isinstance(value, dict):
            file_handle.write(f'{indent}{key}:\n')
            _write_yaml_entries(file_handle, value, indent + '   ')
        elif isinstance(value, str):
            file_handle.write(f'{indent}{key}: {value}\n')
        else:
            file_handle.write(f'{indent}{key}: {value!r}\n')


def write_camera_yaml(camera_path, camera_values):
    with open(camera_path, 'w') as file_handle:
        file_handle.write('%YAML:1.0\n---\n')
        file_handle.write('# GENERATED FILE - DO NOT EDIT BY HAND.\n')
        file_handle.write(
            f'# Source of truth: cine_sensing_config/config/profiles/'
            f'{cine_sensing_config.active_profile()}/{PROFILE_CAMERA_CONFIG_NAME}.json\n'
        )
        _write_yaml_entries(file_handle, camera_values)


def _banner_lines():
    profile = cine_sensing_config.active_profile()
    if profile:
        profile_line = (
            f'# Profile: {profile} (files in cine_sensing_config/config/profiles/{profile}/ '
            'replace the base files)'
        )
    else:
        profile_line = '# Profile: none (base files only)'

    return [
        '# ===================================================================',
        '# GENERATED FILE - DO NOT EDIT BY HAND.',
        '# Source of truth: cine_sensing_config/config/vins.json',
        profile_line,
        '# Regenerated by generate_vins_config.py on every VIO launch.',
        '# Edits here are silently overwritten and produce invalid metrics.',
        '# ===================================================================',
    ]


def generate_config(output_path, share_directory_lookup=package_share_directory):
    print('Generating VINS configuration using centralized parameters...')
    output_directory = os.path.dirname(os.path.abspath(output_path))
    os.makedirs(output_directory, exist_ok=True)

    camera_values = profile_camera_values()
    if camera_values is not None:
        output_stem = os.path.splitext(os.path.basename(output_path))[0]
        camera_path = os.path.join(output_directory, f'{output_stem}_cam0.yaml')
        write_camera_yaml(camera_path, camera_values)
    else:
        camera_path = installed_camera_file(VinsConfig.CAM0_CALIB, share_directory_lookup)

    config = {
        'imu': VinsConfig.IMU,
        'num_of_cam': VinsConfig.NUM_OF_CAM,
        'imu_topic': VinsConfig.IMU_TOPIC,
        'image0_topic': VinsConfig.IMAGE0_TOPIC,
        'output_path': os.path.join(os.path.expanduser('~'), VinsConfig.OUTPUT_PATH),
        'cam0_calib': os.path.relpath(camera_path, output_directory),
        'image_width': CameraConfig.IMAGE_WIDTH,
        'image_height': CameraConfig.IMAGE_HEIGHT,
        'estimate_extrinsic': VinsConfig.ESTIMATE_EXTRINSIC,
        'body_T_cam0': VinsConfig.BODY_T_CAM0,
        'multiple_thread': VinsConfig.MULTIPLE_THREAD,
        'feature_tracker': VinsConfig.FEATURE_TRACKER,
        'min_parallax': VinsConfig.MIN_PARALLAX,
        'max_cnt': VinsConfig.MAX_CNT,
        'min_dist': VinsConfig.MIN_DIST,
        'freq': VinsConfig.FREQ,
        'F_threshold': VinsConfig.F_THRESHOLD,
        'detect_threshold': VinsConfig.DETECT_THRESHOLD,
        'show_track': VinsConfig.SHOW_TRACK,
        'flow_back': VinsConfig.FLOW_BACK,
        'equalize': VinsConfig.EQUALIZE,
        'clahe_clip': VinsConfig.CLAHE_CLIP,
        'pyramid_levels': VinsConfig.PYRAMID_LEVELS,
        'win_size': VinsConfig.WIN_SIZE,
        'keyframe_parallax': VinsConfig.KEYFRAME_PARALLAX,
        'acc_n': VinsConfig.ACC_N,
        'gyr_n': VinsConfig.GYR_N,
        'acc_w': VinsConfig.ACC_W,
        'gyr_w': VinsConfig.GYR_W,
        'g_norm': VinsConfig.G_NORM,
        'gravity_aligned': VinsConfig.GRAVITY_ALIGNED,
        'estimate_td': VinsConfig.ESTIMATE_TD,
        'td': VinsConfig.TD,
        'tr': VinsConfig.TR,
        'loop_closure': VinsConfig.LOOP_CLOSURE,
        'load_previous_pose_graph': VinsConfig.LOAD_PREVIOUS_POSE_GRAPH,
        'pose_graph_save_path': os.path.join(
            os.path.expanduser('~'), VinsConfig.POSE_GRAPH_SAVE_PATH
        ),
        'save_image': VinsConfig.SAVE_IMAGE,
        'use_depth': VinsConfig.USE_DEPTH,
        'depth_topic': VinsConfig.DEPTH_TOPIC,
    }

    with open(output_path, 'w') as file_handle:
        file_handle.write('%YAML:1.0\n')
        file_handle.write('---\n\n')
        file_handle.write('\n'.join(_banner_lines()) + '\n\n')
        for key, value in config.items():
            if isinstance(value, dict) and 'rows' in value:
                file_handle.write(f'{key}:\n')
                file_handle.write(f'  rows: {value["rows"]}\n')
                file_handle.write(f'  cols: {value["cols"]}\n')
                file_handle.write(f'  dt: {value["dt"]}\n')
                file_handle.write(f'  data: {value["data"]}\n')
            elif isinstance(value, list):
                file_handle.write(f'{key}: {value}\n')
            elif isinstance(value, str):
                file_handle.write(f'{key}: "{value}"\n')
            else:
                file_handle.write(f'{key}: {value}\n')

    print(f'Generated VINS config at {output_path}')


if __name__ == '__main__':
    if len(sys.argv) > 1:
        output_path = sys.argv[1]
    else:
        output_path = os.path.join(os.path.dirname(__file__), 'generated_vins_config.yaml')

    try:
        generate_config(output_path)
    except (OSError, LookupError, ValueError) as error:
        print(f'Error generating VINS config: {error}')
        sys.exit(1)
